grid.grid-template-columns:
[[[
  /* Four columns, and the name still has to sit on the card's centre.
     Writing out the arithmetic: with three 5px gaps, the middle column
     runs from L+5 to W-(K+A+10), so its centre is the card's only when
     L = A + K + 5. The room icon needs 26px whatever else is going on,
     so L floors there and the alert column takes up the slack - empty
     space on the right, which is what keeps a room with no badges
     centred just as well as one with two. */
  const groups = (window.charroAlertGroups ? window.charroAlertGroups(variables, states) : []);
  const lock = (window.charroLockBadge ? window.charroLockBadge(variables, states) : null);
  const k = lock ? 26 : 0;
  const l = Math.max(26, 26 * groups.length + k + 5);
  return `${l}px 1fr ${l - k - 5}px ${k}px`;
]]]

icon.color:
[[[
  const all = [].concat(variables.light_entities || [], variables.landscape_entities || []);
  const on = all.some(e => states[e]?.state === 'on');
  return on ? variables.pal.amber.fg : 'var(--primary-text-color)';
]]]

name.font-size:
[[[
  const n = Math.max((variables.room_name || '').length, 1);
  const groups = (window.charroAlertGroups ? window.charroAlertGroups(variables, states) : []);
  const lock = (window.charroLockBadge ? window.charroLockBadge(variables, states) : null);
  /* Both side columns, all three gaps and the card's own padding. The
     left column is the whole right-hand side plus a gap, by the
     arithmetic above, so the reserve is twice it plus the rest. */
  const l = Math.max(26, 26 * groups.length + (lock ? 26 : 0) + 5);
  const reserve = 30 + 2 * l;
  /* 1.72, not 1.6: measured in Roboto Bold, these room names run about
     10.4px per character at 18px at their widest ("Javon"), where 1.6
     budgets 11.25px — so an 11-character name was shrunk a step further
     than it had to be */
  return `clamp(11px, calc((100cqw - ${reserve}px) / ${n} * 1.72), 18px)`;
]]]

