  return n > 1 ? String(n) : '';
]]]

card.icon:
[[[
  const s = states[variables.climate_entity]?.state;
  if (s === 'cool') return 'mdi:snowflake';
  if (s === 'heat') return 'mdi:fire';
  if (s === 'heat_cool') return 'mdi:sun-snowflake-variant';
  return 'mdi:thermostat';
]]]

card.name:
[[[
  const st = states[variables.climate_entity];
  if (!st) return '';
  const a = st.attributes || {};
  const t = (st.state === 'off') ? (a.current_temperature ?? a.temperature)
                                 : (a.temperature ?? a.current_temperature);
  return t != null ? `${Math.round(t)}°` : '';
]]]

card.background:
[[[
  const st = states[variables.climate_entity];
  const s = st?.state;
  const a = st?.attributes || {};
  const act = a.hvac_action;
  const cur = a.current_temperature, set = a.temperature;
  const known = cur != null && set != null;
  if (!s || s === 'off' || s === 'unavailable') return variables.pal.off.bg;
  /* what the unit is actually doing beats what it is set to */
  if (act === 'cooling') return variables.pal.blue.bg;
  if (act === 'heating') return variables.pal.red.bg;
  if (act === 'idle' || act === 'fan') return variables.pal.green.bg;
  /* no hvac_action: fall back to current vs target */
  if (s === 'cool') return (known && cur <= set) ? variables.pal.green.bg : variables.pal.blue.bg;
  if (s === 'heat') return (known && cur >= set) ? variables.pal.green.bg : variables.pal.red.bg;
  if (s === 'heat_cool') return variables.pal.purple.bg;
  return variables.pal.off.bg;
]]]

